SELECT CASE WHEN rating >= 3.8 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END rating_bucket, city, COUNT(CASE WHEN city = 'London' THEN 1 END) london_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) city_values FROM suppliers WHERE (rating > 3.2 AND city = 'Tokyo') OR LENGTH(supplier_name) > 12 GROUP BY 1, 2 HAVING SUM(CASE WHEN city = 'Singapore' THEN rating ELSE 0 END) > 76;
